mapper.select:
select EMPLOYEE_CODE,group_concat(FACTORY_ID) as FACTORY_ID
from safety_park_employee_power_info
where IS_DELETE = 0
  and POWER_end_TIME >= #{powerBeginTime}

  and POWER_end_TIME < #{powerEndTime}

group by EMPLOYEE_CODE

select m.emp_no,m.emp_name,m.phone_no,group_concat(ei.FACTORY_ID) as factory_id,max(ei.POWER_END_TIME) as power_end_time from safety_employee_message m left join safety_park_employee_power_info ei on m.emp_no = ei.EMPLOYEE_CODE and ei.IS_DELETE = '0' where m.status = 'NORMAL' and m.emp_no in
#{ll}
and ei.POWER_END_TIME > now() group by m.emp_no, m.emp_name, m.phone_no

select pi.id, pi.EMPLOYEE_CODE, pi.FACTORY_ID, pi.POWER_BEGIN_TIME, pi.POWER_END_TIME, pi.REMARK, pi.CREATE_TIME, pi.UPDATE_TIME, pi.IS_DELETE, m.field_name as factory_name, pi.down_mark from safety_park_employee_power_info pi left join safety_field_manage m on pi.FACTORY_ID = m.id and m.delete_falg = '0' where pi.IS_DELETE = '0'
and pi.EMPLOYEE_CODE = #{empNo}
and pi.EMPLOYEE_CODE in
#{item}
